				format: "w8a8", M: M, N: N, block: block,
				weightBytes: M * N,
				fillWeights: fillInt8Pattern,
				kind:        coldInt8Acts,
			}, warmup, iters)
			if err != nil {
				return nil, fmt.Errorf("gemv_cold w8a8 block=%d footprint=%dMB: %w", block, fpMB, err)
			}
