for fam,filt in (('gemm_wmma',lambda r: r['size']=='1024'),('gemv_cold',lambda r: 'weightMB=1' in r['detail'] or True)):
    new={(r['variant'],r['weight_format'],r['block_size'],r['size'],r['detail']):float(r['gflops'])
         for r in csv.DictReader(open('$SP/regress/%s.csv'%fam))}
    old={(r['variant'],r['weight_format'],r['block_size'],r['size'],r['detail']):float(r['gflops'])
         for r in csv.DictReader(open('results/%s.csv'%fam)) if filt(r)}
    common=set(new)&set(old)
    d=sorted((abs(new[k]/old[k]-1),k) for k in common if old[k]>0)
    print('%-10s new=%d committed(matching)=%d common=%d median %.2f%% max %.1f%% (%s)'%(
        fam,len(new),len(old),len(common),100*statistics.median([x[0] for x in d]),100*d[-1][0],d[-1][1][0]))
